import {initI18n, localizeDOM, friendlyError, translate, formatMessage, currentLocale} from "./i18n.js";
import {installControls} from "./controls.js";
const FILTER_KEYS=["groups","resolutions","subtitles"];
const BUILTIN_SOURCES=["dmhy","nyaa","mikan"];
export function seasonPresentation(s){if(!s.inventory_known)return{kind:"unknown",text:s.inventory_error?formatMessage("Unable to read media library: {error}",{error:s.inventory_error}):"Unable to read media library"};if(s.status==="conflict")return{kind:"conflict",text:s.detail||"Episode mapping needs attention"};if(s.status==="incomplete")return{kind:"incomplete",text:formatMessage("Missing internally {count} episodes: {episodes}",{count:s.missing?.length||0,episodes:(s.missing||[]).join(", ")})};return{kind:"continuous",text:"Current files are continuous"}}
export function canCompleteSeason(s){return Boolean(s?.inventory_known&&s.status!=="conflict")}
export function list(v){return Array.isArray(v)?v:[]}
export function discoverySources(group,acquireSource=""){return acquireSource?[acquireSource]:list(group?.source_ids)}
export function previewNameValid(name){return Boolean(String(name||"").trim())}
export function clearEntrySelection(s){s.entry=null;s.seasons=[];s.folders=[]}
export function newClientModel(){return{id:"",type:"qbittorrent",url:"",username:"",credential_set:false,path_mappings:[],enabled:true}}
export function issueText(v){return [v?.message,v?.hint].filter(Boolean).map(friendlyError).join(" — ")}
export function renderIssues(values){return list(values).map(v=>`<div class="notice ${v?.severity==="error"?"error":""}"><strong>${esc(translate(v?.stage||"Operation"))} · ${esc(translate(v?.code||v?.severity||"issue"))}</strong><p>${esc(issueText(v))}</p><small>${esc([v?.entry,v?.source,v?.client,v?.task].filter(Boolean).join(" · "))}</small></div>`).join("")}
export function setupComplete(c){const o=c?.organizer;return Boolean(o?.source&&o?.target&&Object.values(c?.clients||{}).some(x=>x.enabled))}
export function uiCapabilities(c){const sources=Object.values(c?.sources||{}).filter(x=>x.enabled),o=c?.organizer;return{roots:Boolean(o?.source&&o?.target),clients:Object.values(c?.clients||{}).some(x=>x.enabled),sources:sources.length>0}}
export function buildOutput(title){return{title:String(title||"").trim()}}
export function buildMovieClassify(value){return Object.fromEntries(lines(value).map(line=>{const i=line.indexOf("=");if(i<1)throw new Error(formatMessage("Invalid Movie classification rule: {rule}",{rule:line}));return[line.slice(0,i).trim(),line.slice(i+1).trim()]}).filter(([,kind])=>kind.toLowerCase()!=="auto"))}
export function movieClassifyText(values){return Object.entries(values||{}).map(([path,kind])=>`${path} = ${kind}`).join("\n")}
export function buildEntryDeclaration(base,values){const out={...base,...values,output:buildOutput(values.output_title),blacklist:lines(values.blacklist)};delete out.output_title;const classify=values.movie_classify??globalThis.document?.querySelector?.("#entry-movie-classify")?.value;if(classify!==undefined){out.movie={classify:buildMovieClassify(classify)};delete out.movie_classify}return out}
export function blacklistText(values){return(values||[]).join("\n")}
export function bindEntryItems(container,load){if(!container)return;const open=item=>load(item.dataset.entryId);for(const item of container.querySelectorAll?.("[data-entry-id]")||[])item.onclick=e=>{e.stopPropagation?.();open(item)};container.onclick=e=>{const item=e.target.closest?.("[data-entry-id]");if(item&&container.contains(item)&&!item.onclick)open(item)}}
export function previewPresentation(r){const excluded=r?.decision==="excluded";return{excluded,title:excluded?"Excluded":"Mapping result",rule:excluded?(String(r.reason||"").match(/"([^"]+)"/)?.[1]||""):"",source:r?.source_episode,target:r?.target_episode,sourceTitle:r?.parsed?.title||"",outputTitle:r?.output_title||"",path:r?.expected_path||""}}
export function migrationSeason(mediaType,seriesSeason){return mediaType==="series"?Number(seriesSeason):0}
export function migrationSeasonField(id,mediaType,season=1){return mediaType==="series"?field("Season",`<input id="${id}-season" data-migration-season type="number" min="0" max="99" value="${esc(season??1)}">`):""}
export function migrationDecisionPresentation(decision){return({adopt:{ready:true,label:"No move needed",kind:"adopt"},relocate:{ready:true,label:"Relocation needed",kind:"relocate"},conflict:{ready:false,label:"Ownership needs confirmation",kind:"conflict"},unknown:{ready:false,label:"Cannot determine ownership automatically",kind:"unknown"},skip:{ready:false,label:"Managed",kind:"skip"}})[decision]||{ready:false,label:String(decision||"Unknown"),kind:"unknown"}}
export function migrationActionSummary(plans){const decisions=list(plans).map(p=>p?.decision);return{count:decisions.length,relocate:decisions.filter(x=>x==="relocate").length,adopt:decisions.filter(x=>x==="adopt").length,blocked:decisions.filter(x=>x!=="relocate"&&x!=="adopt").length}}
export function migrationConfirmationModel(plans,{title="",mediaType="series",season=0}={}){const summary=migrationActionSummary(plans),name=String(title||"Untitled Library").trim()||"Untitled Library",scope=mediaType==="movie"?formatMessage("“{name}”",{name}):formatMessage("“{name}” Season {number}",{name,number:String(Number(season)||0).padStart(2,"0")});if(summary.blocked)return{title:"Confirm download task ownership",confirmLabel:"Confirm and execute",kind:"resolve",message:formatMessage("Assign {count} task(s) to {scope} and adjust save locations as needed. The state will be checked again before execution; if ownership still cannot be determined, correct the title information first.",{count:summary.count,scope})};if(summary.relocate)return{title:"Execute migration",confirmLabel:"Execute migration",kind:"relocate",message:formatMessage("Will process {count} task(s); {relocate} will be relocated by the downloader. Confirm that the downloader can access the target directory.",{count:summary.count,relocate:summary.relocate})};return{title:"Confirm title ownership",confirmLabel:"Confirm",kind:"adopt",message:formatMessage("Confirm that {count} task(s) belong to {scope}. Existing downloaded files do not need to move; after confirmation they will be managed automatically.",{count:summary.count,scope})}}

// Display preferences never change acquisition policy or the backend projection.
export function discoveryDisplayOrder(groups,order=[]){const rank=new Map(list(order).map((id,i)=>[id,i])),score=g=>Math.min(rank.size,...list(g?.source_ids).map(id=>rank.get(id)??rank.size));return list(groups).map((g,i)=>({g,i})).sort((a,b)=>score(a.g)-score(b.g)||a.i-b.i)}
export function readDiscoveryOrder(storage){try{return [...new Set(list(JSON.parse(storage?.getItem("aninode.discoveryOrder")||"[]")).filter(x=>typeof x==="string"))]}catch{return []}}
function currentDiscoveryOrder(){try{return readDiscoveryOrder(globalThis.localStorage)}catch{return []}}
function openDiscoveryOrder(){let order=currentDiscoveryOrder();const sources=Object.values(state.config.sources||{}).filter(x=>x.enabled&&state.config.source_capabilities?.[x.id]?.current),ids=sources.map(x=>x.id);order=[...order.filter(id=>ids.includes(id)),...ids.filter(id=>!order.includes(id))];modal(`<h2>Discovery display order</h2><p>Titles from earlier sources are shown first; titles found by multiple sources use the earliest source. This preference is saved only in this browser and does not affect download priority.</p><ol id="discovery-order" class="display-order"></ol><div class="toolbar between">${button("Restore defaults",'id="reset-discovery-order"')}<div>${button("Cancel",'id="cancel"')}${button("Save",'id="save-discovery-order" class="primary"')}</div></div>`);const draw=()=>{$("#discovery-order").innerHTML=order.map((id,i)=>`<li><span>${esc(sourceName(state.config.sources[id]))}</span><div>${button("Move up",`data-order-index="${i}" data-order-step="-1" aria-label="${esc(formatMessage("Move up {name}",{name:sourceName(state.config.sources[id])}))}" ${i===0?"disabled":""}`)}${button("Move down",`data-order-index="${i}" data-order-step="1" aria-label="${esc(formatMessage("Move down {name}",{name:sourceName(state.config.sources[id])}))}" ${i===order.length-1?"disabled":""}`)}</div></li>`).join("");$$('[data-order-step]').forEach(x=>x.onclick=()=>{const i=Number(x.dataset.orderIndex),next=i+Number(x.dataset.orderStep);[order[i],order[next]]=[order[next],order[i]];draw();const row=$("#discovery-order").children[next];row.querySelector('button:not(:disabled)')?.focus()})};draw();$("#cancel").onclick=closeModal;const save=values=>{try{localStorage.setItem("aninode.discoveryOrder",JSON.stringify(values));closeModal();render();$("#discovery-order-open")?.focus();toast("Display order saved")}catch{modalError("Unable to save display order. Check browser storage permissions.")}};$("#save-discovery-order").onclick=()=>save(order);$("#reset-discovery-order").onclick=()=>save([])}

const initialState=()=>({authenticated:false,config:null,diagnostics:null,clientStatuses:[],catalogEntries:[],error:"",syncError:"",view:"entries",entry:null,seasons:[],folders:[],migration:null,migrationBusy:"",migrationScanning:false,discoveries:[],rssDiscoveries:[],rssDiscoveryIssues:[],rssDiscoveryError:"",rssSources:[],rssRefreshing:false,rssReadPending:false,rssRefreshPending:false,discoveryQuery:"",entryQuery:"",discoveryLocalQuery:""});
const state=initialState();
let sessionEpoch=0;
let runtimeConnectionError=false;
let modalReturnFocus=null;
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);
export function safeExternalURL(value){try{const u=new URL(String(value||"").trim());return u.protocol==="http:"||u.protocol==="https:"?u.toString():""}catch{return""}}
const lines=v=>String(v||"").split("\n").map(x=>x.trim()).filter(Boolean),checked=v=>v?"checked":"";
async function api(path,options={}){const epoch=sessionEpoch,headers={"X-Aninode-Request":"1",Accept:"application/json",...(options.headers||{})},signal=options.signal||AbortSignal.timeout(50000);if(options.body!==undefined)headers["Content-Type"]="application/json";let response;try{response=await fetch(path,{...options,headers,signal,credentials:"same-origin",cache:"no-store"})}catch(e){if(e.name==="TimeoutError"||e.name==="AbortError")throw new Error(friendlyError("Server response timed out; the operation may still be running. Refresh later to confirm."));throw new Error(friendlyError(e.message||"Unable to connect to server"))}let value;try{value=await response.json()}catch{value=null}if(path.startsWith("/ui/")&&epoch!==sessionEpoch)throw new Error("Sign-in state changed");if(response.status===401&&(path.startsWith("/ui/")||value?.error?.code==="unauthorized")){showLogin(false,"Sign-in expired. Please sign in again.");throw new Error("Please sign in again")}if(!response.ok)throw new Error(friendlyError(value?.error?.message||`HTTP ${response.status}`));return value}
function entryURL(key){const i=String(key||"").indexOf("/");if(i<1)throw new Error("Invalid directory key");return`/ui/catalog/${encodeURIComponent(key.slice(0,i))}/${encodeURIComponent(key.slice(i+1))}`}
const button=(label,attrs="")=>`<button ${attrs}>${translate(label)}</button>`;
const field=(label,control,hint="")=>`<label class="field"><span>${translate(label)}</span>${control}${hint?`<small>${translate(hint)}</small>`:""}</label>`;
const input=(id,value="",type="text",placeholder="")=>`<input id="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(translate(placeholder))}">`;
const textarea=(id,value="",placeholder="")=>`<textarea id="${id}" placeholder="${esc(translate(placeholder))}">${esc(value)}</textarea>`;
const options=(values,selected="",empty="")=>`${empty?`<option value="">${esc(empty)}</option>`:""}${values.map(v=>`<option value="${esc(v)}" ${v===selected?"selected":""}>${esc(v)}</option>`).join("")}`;
const SOURCE_NAMES={dmhy:"DMHY",nyaa:"Nyaa",mikan:"Mikan",generic:"Custom source"};
const CLIENT_NAMES={qbittorrent:"qBittorrent",transmission:"Transmission",aria2:"aria2"};
function sourceName(source){return translate(SOURCE_NAMES[source?.provider]||source?.id||"Content source")}
function clientName(client){return CLIENT_NAMES[client?.type]||client?.type||client?.id||"Downloader"}
function namedOptions(values,selected="",empty=""){return `${empty?`<option value="">${esc(empty)}</option>`:""}${values.map(v=>`<option value="${esc(v.value)}" ${v.value===selected?"selected":""}>${esc(v.label)}</option>`).join("")}`}
function nextConfigID(kind,base){const values=state.config?.[kind]||{},clean=String(base||kind).toLowerCase().replace(/[^a-z0-9_-]+/g,"-").replace(/^-+|-+$/g,"")||kind;if(!values[clean])return clean;for(let i=2;;i++){const id=`${clean}-${i}`;if(!values[id])return id}}
function toast(message){if(!$("#toast"))return;$("#toast").innerHTML=`<div class="toast" role="status">${esc(translate(message))}</div>`;setTimeout(()=>{if($("#toast"))$("#toast").innerHTML=""},3200)}
function fail(message){state.error=message;render()}
function modal(content){$("#overlay").dataset.page=state.view;modalReturnFocus=document.activeElement;$("#overlay").innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button type="button" class="modal-close" aria-label="Close dialog">×</button><div id="modal-error" aria-live="polite"></div>${content}</section></div>`;const dialog=$(".modal");dialog.querySelector("h2")?.setAttribute("id","modal-title");dialog.querySelector(".modal-close").onclick=closeModal;dialog.querySelector("input,select,textarea,button:not(.modal-close)")?.focus();$(".modal-backdrop").onclick=e=>{if(e.target===e.currentTarget)closeModal()}}
function closeModal(){if($("#overlay"))$("#overlay").innerHTML="";modalReturnFocus?.focus?.();modalReturnFocus=null}function modalError(message){if(!$("#modal-error"))return;$("#modal-error").innerHTML=`<div class="notice error" role="alert">${esc(translate(message))}</div>`}
function confirmAction({title,message,confirmLabel="Confirm",danger=false},onConfirm){modal(`<h2>${esc(translate(title))}</h2><div class="confirmation-copy"><p>${esc(translate(message))}</p></div><div class="toolbar end">${button("Cancel",'id="cancel-confirm"')}${button(esc(confirmLabel),`id="confirm-action" class="${danger?"danger":"primary"}"`)}</div>`);$("#cancel-confirm").onclick=closeModal;$("#confirm-action").onclick=()=>{closeModal();onConfirm?.()}}
function scrollToID(id){const views={migration:"migration",discovery:"discovery",entries:"entries",settings:"settings"};state.view=views[id]||id;render();$("#main")?.focus({preventScroll:true});window.scrollTo({top:0,behavior:"smooth"});if(state.view==="settings")loadClientStatuses()}
async function runAutomation({quiet=false}={}){try{const r=await api("/ui/automation/run",{method:"POST",body:"{}"});if(!quiet)toast(r.status==="coalesced"?"Check already in progress":"Check started");return r}catch(e){if(!quiet)toast(formatMessage("Failed to trigger background check: {error}",{error:e.message}));return null}}
function entrySearchRankUI(v,query){query=String(query||"").trim().toLowerCase();if(!query)return 0;const w=v?.entry||{},d=v?.declaration||{},values=[w.title,d.output?.title].filter(Boolean).map(x=>String(x).toLowerCase());let best=-1;for(const value of values){const rank=value===query?0:value.startsWith(query)?1:value.includes(query)?2:-1;if(rank>=0&&(best<0||rank<best))best=rank}return best}
function filteredEntries(values=state.catalogEntries,query=state.entryQuery){const q=String(query||"").trim();return list(values).filter(v=>entrySearchRankUI(v,q)>=0).sort((a,b)=>{const issueRank=x=>({conflict:0,incomplete:1,unknown:2,managed:3,complete:3,disabled:4}[x?.summary?.status]??2),ar=issueRank(a),br=issueRank(b);if(ar!==br)return ar-br;const aq=entrySearchRankUI(a,q),bq=entrySearchRankUI(b,q);if(aq!==bq)return aq-bq;return String(a?.entry?.title||"").localeCompare(String(b?.entry?.title||""),"zh-CN")})}
export function projectionFromResponses(values,selected=""){const snapshot={config:values[0],diagnostics:values[1],catalogEntries:list(values[2])};if(selected){snapshot.entry=values[3];snapshot.seasons=list(values[3]?.seasons);snapshot.folders=list(values[3]?.folders)}return snapshot}
async function backendProjection(){const selected=state.entry?.entry?.key||"",requests=[api("/ui/config"),api("/ui/diagnostics"),api("/ui/catalog")];if(selected)requests.push(api(entryURL(selected)));return projectionFromResponses(await Promise.all(requests),selected)}
function applyBackendProjection(snapshot){state.config=snapshot.config;state.diagnostics=snapshot.diagnostics;state.catalogEntries=snapshot.catalogEntries;if(snapshot.clientStatuses)state.clientStatuses=snapshot.clientStatuses;if(Object.hasOwn(snapshot,"entry")){state.entry=snapshot.entry;state.seasons=snapshot.seasons;state.folders=snapshot.folders}else if(state.entry&&!snapshot.catalogEntries.some(x=>x?.entry?.key===state.entry.entry.key))clearEntrySelection(state);state.syncError="";runtimeConnectionError=false}
function editingUI(){const active=document.activeElement;return Boolean(active&&(active.matches?.("input,select,textarea")||active.closest?.(".modal")))}
async function reloadProjection({renderPage=true}={}){try{const snapshot=await backendProjection();applyBackendProjection(snapshot);if(renderPage&&!editingUI())render();else renderRuntime();return true}catch(e){state.syncError=e.message;runtimeConnectionError=true;renderRuntime();return false}}
async function refresh(){if(!state.authenticated)return;state.error="";const ok=await reloadProjection();if(!ok)fail(state.syncError||"Unable to reload aninode");else if(state.view==="discovery")loadRSSDiscoveries()}
function shell(){$("#app").innerHTML=`<div class="app-frame"><aside class="sidebar"><div class="brand"><strong>aninode</strong><span>media organizer</span></div><nav id="nav" aria-label="Main navigation"></nav><div class="spacer"></div><div class="sidebar-foot"><span class="sidebar-caption">Service status</span><div id="runtime" class="runtime failed" role="status">Waiting for connection</div>${button("Change Password",'id="login-password-button" class="connection-button"')}${button("Sign out",'id="logout-button" class="connection-button"')}</div></aside><main id="main" class="main" tabindex="-1"></main></div><div id="overlay"></div><div id="toast" aria-live="polite" aria-atomic="true"></div>`;$("#logout-button").onclick=logout;$("#login-password-button").onclick=openLoginPassword}
function render(){if(!state.authenticated||!state.config||!$("#main"))return;const caps=uiCapabilities(state.config),nav=[["entries","Library"],...(caps.sources?[["discovery","Discover"]]:[]),...(caps.clients?[["migration","Migration"]]:[]),["settings","Settings"]];if(!nav.some(([id])=>id===state.view))state.view="entries";$("#main").dataset.page=state.view;$("#nav").innerHTML=nav.map(([id,label],i)=>button(`<span class="nav-no">${String(i+1).padStart(2,"0")}</span><span class="nav-label">${label}</span>`,`data-view="${id}" ${state.view===id?'class="active" aria-current="page"':""}`)).join("");const content={migration:()=>caps.clients?migrationView():prompt("migration","Add a downloader before checking tasks for migration","Go to Settings"),discovery:()=>caps.sources?discovery():prompt("discovery","Enable a content source to discover titles","Go to Settings"),entries,settings};$("#main").innerHTML=`${state.error?`<div class="notice error" role="alert">${esc(state.error)}</div>`:""}${content[state.view]()}`;renderRuntime();bind()}
function renderRuntime(){const ready=!runtimeConnectionError&&state.diagnostics?.runtime_config==="ready",runtime=$("#runtime");if(runtime){runtime.className=`runtime ${ready?"ready":"failed"}`;runtime.textContent=runtimeConnectionError?"Connection issue":ready?"Running normally":"Needs attention";runtime.title=state.syncError||""}const detail=$("#runtime-diagnostics");if(detail)detail.innerHTML=diagnostics()}
function prompt(id,text,label){return`<section id="${id}" class="section"><article class="setup-prompt"><p>${text}</p>${button(label,'data-scroll="settings" class="primary"')}</article></section>`}
function migrationView(){const scanAttrs=`data-migration-plan ${state.migrationScanning?"disabled aria-busy=\"true\"":""}`,scanLabel=state.migrationScanning?"Scanning…":"Scan downloader",startLabel=state.migrationScanning?"Scanning…":"Start scan";return`<section id="migration" class="section migration-page"><header class="page-heading"><div><span class="overline">Download tasks</span><h1>Migration</h1><p>Bring existing download tasks under title management. Scan first, then review and confirm migration.</p></div><div class="page-actions">${button(scanLabel,scanAttrs)}</div></header><div class="bench-body">${state.migration?renderMigration(state.migration):`<div class="bench-empty migration-empty"><span class="overline">Start organizing</span><strong>${state.migrationScanning?"Scanning download tasks":"Download tasks have not been scanned yet"}</strong><p>${state.migrationScanning?"Reloading downloader tasks and analyzing title ownership. Keep this page open.":"Click “Start scan” to find tasks pending organization. Save locations change only after you confirm the migration."}</p>${button(startLabel,scanAttrs)}</div>`}</div></section>`}
export function renderMigration(value){
  const groups=list(value?.groups);
  if(!groups.length)return`<div class="bench-empty compact"><strong>No tasks need migration</strong><p>Tasks already in the matching title download directory do not need migration.</p></div>`;
  const sorted=[...groups].sort((a,b)=>Number(b?.blocked||0)-Number(a?.blocked||0));
  const allPlans=sorted.flatMap(g=>list(g?.plans)),summary=migrationActionSummary(allPlans);
  const cards=sorted.map((g,i)=>{
    const plans=list(g?.plans),id=`migration-${i}`,movie=g?.media_type==="movie",busy=state.migrationBusy===g?.key,blocked=Number(g?.blocked||0),needsClassify=plans.some(p=>/movie (bundle|assets?).*classif/i.test(p?.detail||""));
    const blockedText=needsClassify?"Confirm the title information and classify the main feature, extras, and similar files.":"Verify the title and type. Use the year to distinguish titles with the same name.";
    const allReady=!blocked&&plans.length>0,status=blocked?"Needs confirmation":"Ready";
    const fields=blocked?`<div class="decision-fields">${field("Title",`<input id="${id}-title" data-migration-title value="${esc(g?.title)}">`)}${field("Type",`<select id="${id}-type" data-migration-type><option value="series" ${movie?"":"selected"}>series</option><option value="movie" ${movie?"selected":""}>Movie</option></select>`)}${field("Year (optional)",`<input id="${id}-year" data-migration-year type="number" min="0" max="9999" placeholder="For example, 2024">`)}<div data-migration-season-slot ${movie?"hidden":""}>${migrationSeasonField(id,g?.media_type,g?.season)}</div></div>`:`<div class="migration-hidden-fields"><input id="${id}-title" data-migration-title value="${esc(g?.title)}"><select id="${id}-type" data-migration-type><option value="series" ${movie?"":"selected"}>series</option><option value="movie" ${movie?"selected":""}>Movie</option></select><span data-migration-season-slot ${movie?"hidden":""}>${migrationSeasonField(id,g?.media_type,g?.season)}</span><input id="${id}-year" data-migration-year type="number" value="0"></div>`;
    const taskDetails=`<details class="task-details"><summary><span>${formatMessage("{count} download tasks",{count:plans.length})}</span><small>View tasks and save locations</small></summary><div class="migration-tasks">${plans.map((p,pi)=>{const presentation=migrationDecisionPresentation(p?.decision),explain=presentation.kind==="relocate"?"After execution, the downloader will move the task to the matching title download directory.":presentation.kind==="adopt"?"After confirmation, this title will be managed without moving existing downloaded files.":blockedText;return`<article class="evidence-row"><span class="evidence-index">${String(pi+1).padStart(2,"0")}</span><div><strong>${esc(p?.task_name||p?.task_id)}</strong><small>${esc(translate(presentation.label))}${p?.client?` · ${esc(clientName(state.config?.clients?.[p.client]||{id:p.client}))}`:""}</small>${p?.save_path?`<code>${esc(p.save_path)}</code>`:""}<p>${esc(explain)}</p>${p?.detail?`<details><summary>Technical details</summary><p>${esc(p.detail)}</p></details>`:""}</div></article>`}).join("")}</div></details>`;
    const migrationFilters=`<details class="subpanel migration-filter-panel"><summary>Future release filters (optional)</summary><p class="migration-filter-copy">${formatMessage("These options come from the actual names of files pending migration. Nothing is selected by default, so future releases are unrestricted; only dimensions you explicitly select are written to the title’s {file}.",{file:"<code>.aninode.json</code>"})}</p>${filterEditor(g?.filters||{},g?.filter_options||{})}</details>`;
    return`<article class="migration-group ${blocked?"needs-attention":"ready-unit"}" data-migration-unit="${esc(g?.key)}"><header class="unit-head"><div><span class="unit-kicker">${translate(blocked?"Pending confirmation":"Ready to execute")} · ${String(i+1).padStart(2,"0")}</span><h2>${esc(g?.title||"Unknown Library")}</h2></div><span class="unit-state ${blocked?"attention":"resolved"}">${status}</span></header><div class="unit-facts"><span>${movie?"Movie":formatMessage("series · S{season}",{season:String(g?.season??0).padStart(2,"0")})}</span><span>${formatMessage("{count} tasks",{count:plans.length})}</span></div>${blocked?`<p class="decision-note">${esc(blockedText)}</p>`:""}${fields}<div data-migration-movie-classify ${movie?"":"hidden"}>${blocked&&movie&&needsClassify?field("Movie file classification",`<textarea data-migration-classify placeholder="SPs/trailer.mkv = trailer"></textarea>`,`Format: relative path = version, extra, trailer, interview, featurette, deleted_scene, behind_the_scenes  or  exclude`):""}</div>${migrationFilters}${taskDetails}<footer class="unit-action">${button(busy?"Processing…":allReady?"Execute migration":"Confirm ownership and execute",`class="primary" data-migration-apply="${esc(g?.key)}" ${busy?"disabled":""}`)}</footer></article>`;
  }).join("");
  return`<div class="bench-summary"><span>${formatMessage("{count} titles",{count:sorted.length})}</span><span>${formatMessage("{count} tasks",{count:summary.count})}${summary.relocate?` · ${formatMessage("{count} need relocation",{count:summary.relocate})}`:""}${summary.blocked?` · ${formatMessage("{count} awaiting confirmation",{count:summary.blocked})}`:""}</span></div><div class="migration-grid">${cards}</div>`;
}
function discovery(){const sources=Object.values(state.config.sources||{}).filter(x=>x.enabled),searchable=sources.filter(x=>state.config.source_capabilities?.[x.id]?.discovery),rss=sources.filter(x=>state.config.source_capabilities?.[x.id]?.current);return`<section id="discovery" class="section discovery-page"><header class="page-heading"><div><span class="overline">Series discovery</span><h1>Discover</h1><p>Browse newly released series and follow them for future updates.</p></div></header>${searchable.length?`<section class="archive-search discovery-search-top"><header><span class="overline">Resource search</span><h2>Search for a series</h2><p>Enter a series name to search the selected source for downloadable releases.</p></header><div><div class="searchbar discovery-searchbar"><select id="discovery-source" aria-label="Content source">${namedOptions(searchable.map(x=>({value:x.id,label:sourceName(x)})))}</select><input id="discovery-query" type="search" placeholder="Series name"><button id="discovery-search">Search</button></div><div id="discovery-results">${renderDiscoveries()}</div></div></section>`:""}${rss.length?`<section class="sorting-table"><div class="sorting-tools"><div class="sorting-left"><span class="candidate-count"><strong data-discovery-count>${state.rssDiscoveries.length}</strong><small>series</small></span><span class="sorting-caption">Series available to follow</span></div><div class="sorting-actions"><label class="inline-search"><span aria-hidden="true">⌕</span><input id="rss-discovery-filter" type="search" value="${esc(state.discoveryLocalQuery)}" placeholder="Filter series"></label>${button("Reload",'id="rss-discovery-reload" class="quiet-button"')}${button("Refresh RSS",'id="rss-discovery-refresh" class="quiet-button"')}${button("Display order",'id="discovery-order-open" class="quiet-button"')}${button("Sources",'data-scroll="settings" class="quiet-button"')}</div></div><div id="rss-discovery-status" class="observation-strip" aria-live="polite">${renderRSSStatus()}</div><div id="rss-discovery-results">${renderRSSDiscoveries()}</div></section>`:""}</section>`}
function observedText(g){return [g.groups?.length?formatMessage("Release group {value}",{value:g.groups.join(" / ")}):"",g.subtitles?.length?formatMessage("Subtitle {value}",{value:g.subtitles.join(" / ")}):"",g.resolutions?.length?formatMessage("Quality {value}",{value:g.resolutions.join(" / ")}):""].filter(Boolean).join(" · ")}
function discoveryMetaPills(g){const items=[g.media_type==="movie"?"MOVIE":g.season?`S${String(g.season).padStart(2,"0")}`:"SERIES",...(g.resolutions||[]).slice(0,2),...(g.subtitles||[]).slice(0,2)];return items.filter(Boolean).map((x,i)=>`<span class="discovery-meta ${i===0?"primary-meta":""}">${esc(x)}</span>`).join("")}
function renderRSSDiscoveries(){const issues=(state.rssDiscoveryError?`<div class="notice error" role="alert">${formatMessage("Unable to load the latest RSS results: {error}",{error:esc(state.rssDiscoveryError)})}</div>`:"")+renderIssues(state.rssDiscoveryIssues);if(!state.rssDiscoveries.length){const pending=state.rssSources.some(x=>x.status==="pending"),failed=state.rssSources.some(x=>x.status==="error");return`${issues}<div class="sorting-empty"><strong>${pending?"No RSS results yet":failed?"RSS update failed":"No new series for now"}</strong><span>${pending?"Click “Refresh RSS”, then reload the results later.":failed?"Review the source error and refresh again after it recovers.":"The latest RSS results contain no unmanaged new series."}</span></div>`}const q=state.discoveryLocalQuery.trim().toLowerCase(),values=discoveryDisplayOrder(state.rssDiscoveries,currentDiscoveryOrder()).filter(({g})=>!q||[g.title,g.year,...list(g.groups),...list(g.subtitles),...list(g.resolutions)].filter(Boolean).join(" ").toLowerCase().includes(q));if(!values.length)return`${issues}<div class="sorting-empty"><strong>No matching series</strong><span>Try another search term.</span></div>`;return`${issues}<div class="discovery-grid">${values.map(({g,i},position)=>{const sources=list(g.source_ids).map(id=>sourceName(state.config.sources?.[id]||{id})),releaseCount=g.releases?.length||0;return`<article class="discovery-item"><header class="unit-head compact"><div class="discovery-tags">${discoveryMetaPills(g)}</div><span class="unit-number">${String(position+1).padStart(2,"0")}</span></header><div class="discovery-item-body"><h2>${esc(g.title||"Unknown title")}</h2>${g.year?`<span class="discovery-year">${g.year}</span>`:""}<p class="discovery-groups ${g.groups?.length?"":"muted"}">${esc(g.groups?.length?g.groups.join(" / "):"Unknown release group")}</p></div><div class="unit-facts discovery-facts"><span>${formatMessage("{count} releases",{count:releaseCount})}</span><span>${formatMessage("{count} sources",{count:sources.length})}</span></div><footer class="discovery-item-foot"><span class="source-line">${esc(sources.join(" · ")||"Unknown source")}</span><button type="button" class="discover-action" data-accept-rss="${i}"><span>Follow</span><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h9M8.5 4.5 12 8l-3.5 3.5"/></svg></button></footer></article>`}).join("")}</div>`}
function renderDiscoveries(){if(!state.discoveries.length)return`<div class="empty">Enter a title to start searching.</div>`;return`<div class="search-groups">${state.discoveries.map((g,gi)=>{const releases=list(g.releases);return`<article class="search-group"><header><div><span class="unit-kicker">${g.entry_key?"Managed":"Not managed"}</span><h3>${esc(g.title||"Unknown title")}${g.year?` <em>${g.year}</em>`:""}</h3><small>${esc([formatMessage("{count} releases",{count:releases.length}),observedText(g)].filter(Boolean).join(" · "))}</small></div></header><details class="release-drawer"><summary>${formatMessage("View {count} releases",{count:releases.length})}</summary><div class="release-list">${releases.map((x,ri)=>`<article><div><strong>${esc(x.title)}</strong><small>${esc([x.group,x.episode,x.resolution,x.subtitle].filter(Boolean).join(" · "))}</small></div><div class="toolbar">${safeExternalURL(x.page_url)?`<a class="button" href="${esc(safeExternalURL(x.page_url))}" target="_blank" rel="noreferrer">Details</a>`:""}${x.download_url?button(g.entry_key?"Acquire":"Add and acquire",`class="primary" data-search-release="${gi}:${ri}"`):""}</div></article>`).join("")}</div></details></article>`}).join("")}</div>`}
export function entrySummaryPresentation(v){const s=v?.summary||{},d=v?.declaration||{};if(d.enabled===false||s.status==="disabled")return{kind:"disabled",label:"Disabled",text:"Automation disabled"};if(s.status==="conflict")return{kind:"conflict",label:"Needs attention",text:s.detail||"Mapping conflict"};if(s.reviews>0)return{kind:"incomplete",label:formatMessage("Pending confirmation {count}",{count:s.reviews}),text:formatMessage("{count} low-confidence completion candidate(s)",{count:s.reviews})};if(s.status==="incomplete")return{kind:"incomplete",label:formatMessage("Missing {count} episode(s)",{count:s.missing||0}),text:formatMessage("{count} episode(s) missing",{count:s.missing||0})};if(s.status==="unknown")return{kind:"unknown",label:"Needs attention",text:s.detail||"Unable to load status"};if(s.status==="unobserved")return{kind:"complete",label:"Managed",text:"No recent release information"};if(s.status==="managed")return{kind:"complete",label:"Managed",text:"Movie"};return{kind:"complete",label:"Normal",text:s.seasons?formatMessage("{count} season(s)",{count:s.seasons}):"Normal"}}
function entryList(){const values=filteredEntries();if(!values.length)return`<div class="empty library-empty">${state.entryQuery?"No matching Library.":"No titles yet. Follow a series in “Discover”, or import existing download tasks in “Migration”."}</div>`;const problemCount=values.filter(v=>["conflict","incomplete","unknown"].includes(v?.summary?.status)).length;return`<div class="ledger-caption"><span>${state.entryQuery?formatMessage("Found {count} titles",{count:values.length}):formatMessage("{count} titles",{count:values.length})}</span><span class="${problemCount?"attention-text":"quiet-text"}">${problemCount?formatMessage("{count} pending",{count:problemCount}):"No titles need attention"}</span></div><div class="record-ledger">${values.map((v,i)=>{const w=v.entry,p=entrySummaryPresentation(v),media=w.media_type==="movie"?"Movie":"Series",seasonText=w.media_type!=="movie"&&v.summary?.seasons?formatMessage("{count} seasons",{count:v.summary.seasons}):"—";return`<button type="button" data-entry-id="${esc(w.key)}" class="record-row ${p.kind}"><span class="record-no">${String(i+1).padStart(2,"0")}</span><span class="record-identity"><strong>${esc(w.title)}</strong>${w.year?`<em>${w.year}</em>`:""}</span><span class="record-type">${media}</span><span class="record-scope">${seasonText}</span><span class="record-state ${p.kind}"><i aria-hidden="true"></i><span><strong>${esc(p.label)}</strong><small>${esc(p.text)}</small></span></span><span class="record-open" aria-hidden="true">→</span></button>`}).join("")}</div>`}
function entries(){const configured=setupComplete(state.config);if(state.entry)return`<section id="entries" class="section">${renderManagedEntry()}</section>`;return`<section id="entries" class="section archive-page"><header class="page-heading archive-heading"><div><span class="overline">Media library</span><h1>Library</h1><p>Review managed movies and series, fill missing episodes, or adjust download and organization settings.</p></div><div class="page-actions">${button("Check now",'id="run-automation"')}${button("Refresh",'id="refresh-page" class="quiet-button"')}</div></header>${configured?"":`<div class="notice setup-notice"><div><strong>Initial setup is incomplete</strong><p>Configure working directories and a downloader to start automatic management.</p></div>${button("Go to Settings",'data-scroll="settings" class="primary"')}</div>`}<div class="archive-controls"><label class="inline-search wide"><span aria-hidden="true">⌕</span><input id="entry-search" type="search" value="${esc(state.entryQuery)}" placeholder="Search titles"></label></div><div id="entry-results">${entryList()}</div></section>`}
function renderEntry(){const v=state.entry,w=v.entry,d=v.declaration,movie=w.media_type==="movie",sources=Object.values(state.config.sources||{}).filter(x=>x.enabled),catalog=state.catalogEntries.find(x=>x?.entry?.key===w.key),summary=entrySummaryPresentation(catalog||v);return`<div class="entry-editor"><header class="entry-record-head"><div class="entry-record-main"><button type="button" id="close-entry" class="back-button">← Library</button><span class="overline">${formatMessage("{type} / Title details",{type:translate(movie?"Movie":"Series")})}</span><h1>${esc(w.title)}</h1><div class="entry-record-meta">${w.year?`<span>${w.year}</span>`:""}<span>${d.enabled===false?"Automatic management disabled":"Automatic management enabled"}</span><span class="record-state-inline ${summary.kind}">${esc(translate(summary.label))} · ${esc(translate(summary.text))}</span></div></div>${d.enabled===false?"":button("Check now",'id="run-automation"')}</header><div id="entry-error"></div>${movie?"":`<section class="record-section"><header class="section-heading"><span>01</span><div><h2>Season</h2><p>Review existing and missing episodes, then choose a range to search for gaps.</p></div></header><div id="entry-seasons">${renderSeasons()}</div></section>`}<section class="record-section entry-settings"><header class="section-heading"><span>${movie?"01":"02"}</span><div><h2>Title rules</h2><p>Adjust how this title is downloaded and organized. Filters only save traits you explicitly select.</p></div></header><div class="spec-body entry-settings-sheet"><div class="grid2">${field("Title",input("entry-title",d.title||w.title))}${field("Year",input("entry-year",d.year||w.year||0,"number"),"0 means unset")}</div><label class="check"><input id="entry-enabled" type="checkbox" ${checked(d.enabled)}>Enable automatic management</label><details class="subpanel" open><summary>Content source</summary><div class="field compact-field"><div class="check-list">${sources.map(f=>`<label><input type="checkbox" data-entry-source="${esc(f.id)}" ${checked(list(d.sources).includes(f.id))}>${esc(sourceName(f))}</label>`).join("")}</div><small>Leave unselected to use all enabled sources</small></div></details><details class="subpanel" open><summary>Library naming and file handling</summary>${outputEditor(w,d)}</details><details class="subpanel" open><summary>Release filters</summary>${filterEditor(d.filters||{},v.filter_options||{})}</details>${mappingEditor(d.specials||[],w.media_type)}<details class="subpanel"><summary>Troubleshooting</summary><div class="searchbar"><input id="preview-name" placeholder="Paste a release name or filename">${button("Preview handling",'id="preview-entry"')}</div><div id="preview-result"></div><details class="technical"><summary>Technical details</summary><dl><dt>Declaration path</dt><dd>${esc(w.declaration_path||w.path)}</dd><dt>Internal key</dt><dd>${esc(w.key)}</dd></dl></details></details><div class="commit-row">${button("Save title rules",'id="save-entry" class="primary"')}</div></div></section></div>`}
function outputEditor(w,d){const o=d.output||{},movie=w.media_type==="movie";return`<div class="editor-inner"><div class="grid2">${field("Output title",input("entry-output-title",o.title||""),`Leave blank to use the source title: ${w.title}`)}${field("Skip files (one matching rule per line)",textarea("entry-blacklist",blacklistText(d.blacklist),"*sample*"),"Use * to match any characters; for example, *sample*. Matching is case-insensitive.")}</div>${movie?field("Movie file classification (relative path = type)",textarea("entry-movie-classify",movieClassifyText(d.movie?.classify),"Extras/bonus01.mkv = extra"),"Only needed when automatic classification has a conflict") : ""}</div>`}
function renderManagedEntry(){return renderEntry()}
export function renderFolderCards(folders){if(!list(folders).length)return`<details class="subpanel"><summary>Folder mapping</summary><div class="empty">No folder mapping is needed.</div></details>`;return`<details class="subpanel folder-mapping"><summary>${formatMessage("Folder mapping ({count})",{count:list(folders).length})}</summary><div class="folder-list">${list(folders).map(f=>{const r=f.projection||{},season=r.season??f.suggested_season??1;return`<article class="folder-row" data-folder-card="${esc(f.name)}"><header><strong>${esc(f.name)}</strong><small>→ ${formatMessage("Season {number}",{number:String(season).padStart(2,"0")})}${r.episode_offset?` · ${formatMessage("Episode {offset}",{offset:`${r.episode_offset>0?"+":""}${r.episode_offset}`})}`:""}</small></header><div class="grid2">${field("Target Season",`<input data-folder-season type="number" min="0" max="99" step="1" value="${esc(season)}">`)}${field("Episode offset",`<input data-folder-episode-offset type="number" step="1" value="${esc(r.episode_offset||0)}">`)}</div><details class="technical"><summary>View folder path</summary><code>${esc(f.path||"")}</code></details><div class="toolbar end">${button("Save",`data-save-folder="${esc(f.name)}"`)}</div></article>`}).join("")}</div></details>`}
function renderSeasons(){return`${renderSeasonCards(state.seasons)}${renderFolderCards(state.folders)}`}
function episodeListText(values){const nums=[...new Set(list(values).map(Number).filter(x=>Number.isInteger(x)&&x>0))].sort((a,b)=>a-b);if(!nums.length)return"none";const out=[];for(let i=0;i<nums.length;){let j=i;while(j+1<nums.length&&nums[j+1]===nums[j]+1)j++;const fmt=n=>`E${String(n).padStart(2,"0")}`;out.push(j>i?`${fmt(nums[i])}–${fmt(nums[j])}`:fmt(nums[i]));i=j+1}return out.join(", ")}
function repairEpisodeText(v){const start=Number(v?.episode_start??0),end=Number(v?.episode_end??start);const label=n=>`E${String(n).padStart(2,"0")}`;return end>start?`${label(start)}–${label(end)}`:label(start)}
export function renderRepairReviews(values){const reviews=list(values);if(!reviews.length)return"";return`<section class="repair-review-panel"><header class="repair-review-panel-head"><div><span class="overline">Manual confirmation</span><strong>Episode awaiting confirmation</strong></div><small>These versions will remain even if the next scan temporarily finds nothing; They are removed automatically after the episode is filled or the download is confirmed.</small></header><div class="repair-review-list">${reviews.map(v=>{const r=v.release||{},name=r.media_name||r.title||"Unknown release",diffs=list(v.differences);return`<article class="repair-review"><header><div><span class="repair-review-kicker">${formatMessage("{episode} · uncertain version",{episode:repairEpisodeText(v)})}</span><strong>${esc(name)}</strong></div><span class="repair-review-source">${esc(r.provider||v.source_id||"Historical Search")}</span></header><p>${esc(v.reason||"Automatic completion cannot safely decide whether to use this version. Please confirm manually.")}</p>${diffs.length?`<dl class="repair-differences">${diffs.map(d=>`<div><dt>${esc(d.field)}</dt><dd><span>${esc(d.expected||"Unknown")}</span><b>→</b><strong>${esc(d.candidate||"Unknown")}</strong></dd></div>`).join("")}</dl>`:""}<div class="repair-review-actions"><small>${[r.group,r.resolution,r.subtitle].filter(Boolean).map(esc).join(" · ")}</small>${button("Use this version",`class="primary" data-confirm-repair="${esc(v.id)}" data-repair-season="${esc(v.season)}"`)}</div></article>`}).join("")}</div></section>`}
export function renderSeasonCards(seasons){if(!list(seasons).length)return`<div class="empty">No season information.</div>`;const sorted=[...list(seasons)].sort((a,b)=>{const rank=x=>({conflict:0,incomplete:1,unknown:2,continuous:3}[seasonPresentation(x).kind]??3);return rank(a)-rank(b)||Number(a.season)-Number(b.season)});return`<div class="season-ledger">${sorted.map(s=>{const p=seasonPresentation(s),present=list(s.present_episodes),missing=list(s.missing),targetSeason=s.season,reviews=list(s.repair_reviews),problem=["conflict","incomplete","unknown"].includes(p.kind)||reviews.length>0,label=reviews.length?formatMessage("Pending confirmation {count}",{count:reviews.length}):p.kind==="incomplete"?formatMessage("Missing {count} episode(s)",{count:missing.length}):p.kind==="conflict"?"Needs confirmation":p.kind==="unknown"?"Unknown":"Continuous",min=present.length?Math.min(...present):1,max=present.length?Math.max(...present):1;return`<details class="season-row ${problem?"season-problem":""}" ${problem?"open":""}><summary><span class="season-code">S${String(targetSeason).padStart(2,"0")}</span><span class="season-summary"><strong>${formatMessage("Season {number}",{number:String(targetSeason).padStart(2,"0")})}</strong><small>${reviews.length?formatMessage("{count} low-confidence completion candidate(s) await confirmation",{count:reviews.length}):p.kind==="incomplete"?formatMessage("Missing internally: {episodes}",{episodes:missing.map(x=>`E${String(x).padStart(2,"0")}`).join(", ")}):p.kind==="continuous"?formatMessage("{count} episode(s) · Current files are continuous",{count:present.length}):esc(p.text)}</small></span><span class="season-state ${reviews.length?"conflict":p.kind}"><i></i>${label}</span><span class="season-chevron">⌄</span></summary><div class="season-detail"><dl><dt>Existing</dt><dd>${s.inventory_known?episodeListText(present):"Unable to load"}</dd><dt>Internal gaps</dt><dd>${esc(missing.length?episodeListText(missing):"none")}</dd></dl>${renderRepairReviews(reviews)}${canCompleteSeason(s)?`<div class="range-complete"><label>${translate("Completion range")} E <input type="number" min="1" value="${min}" data-range-from="${targetSeason}"> — E <input type="number" min="1" value="${max}" data-range-through="${targetSeason}"></label>${button("Complete this range",`class="${missing.length?"primary":""}" data-backfill="${targetSeason}"`)}</div>`:""}</div></details>`}).join("")}</div>`}

export function filterEditor(filters={},options={}){const labels={groups:"Release group",resolutions:"Resolution",subtitles:"Subtitle"},help={groups:"When selected, allow only these release groups",resolutions:"When selected, allow only these resolutions",subtitles:"When selected, allow only these subtitle tags"},same=(a,b)=>String(a||"").trim().toLocaleLowerCase()===String(b||"").trim().toLocaleLowerCase();return`<div class="filter-editor">${FILTER_KEYS.map(key=>{const selected=list(filters[key]),values=[];for(const value of [...list(options[key]),...selected])if(value&&!values.some(x=>same(x,value)))values.push(value);values.sort((a,b)=>String(a).localeCompare(String(b),"zh-CN"));return`<fieldset class="filter-dimension"><legend>${labels[key]}</legend><small>${values.length?help[key]:"No options have been observed yet; leave everything unselected for no restriction."}</small><div class="filter-options" data-filter-values="${key}">${values.map(v=>`<label class="filter-option"><input type="checkbox" value="${esc(v)}" ${checked(selected.some(x=>same(x,v)))}><span>${esc(v)}</span></label>`).join("")}</div></fieldset>`}).join("")}<p class="filter-editor-hint">Everything is allowed by default. A category is restricted only after you select at least one value; clear the selection to allow every value in that category again.</p></div>`}
export function readFilters(root){const out={};for(const key of FILTER_KEYS){const values=[...root.querySelectorAll(`[data-filter-values="${key}"] input:checked`)].map(x=>x.value);if(values.length)out[key]=values}return out}
function mappingEditor(specials,mediaType="series"){if(mediaType==="movie")return"";return`<details class="subpanel"><summary>Special file mapping</summary><div class="mapping-editor">${structuredMapping("specials",list(specials),true)}</div></details>`}
function structuredMapping(key,values,enabled){const fields=[["source","Filename (without path)"],["season","Season"],["episode","Episode"]];return`<div class="structured-editor ${enabled?"":"disabled"}" data-structured="${key}"><div class="structured-list">${values.map(v=>structuredRow(key,fields,v,enabled)).join("")}</div>${button("Add",`type="button" data-add-structured="${key}" ${enabled?"":"disabled"}`)}</div>`}
function structuredRow(key,fields,value={},enabled=true){return`<div class="structured-row" data-structured-row="${key}">${fields.map(([name,label])=>field(label,`<input data-field="${name}" ${name==="source"?"":'type="number" min="0"'} value="${esc(value[name]??(name.includes("season")?1:""))}" ${enabled?"":"disabled"}>`)).join("")}${button("Remove",`type="button" data-remove-row class="danger" ${enabled?"":"disabled"}`)}</div>`}
function settings(){const c=state.config,o=c.organizer||{};return`<section id="settings" class="section settings"><header class="page-heading"><div><span class="overline">Preferences and connections</span><h1>Settings</h1><p>Configure downloads, media library, the single downloader, and content sources.</p></div></header><div class="settings-spec"><article class="settings-module spec-section"><header><span class="module-no">01</span><div><h2>Working directories</h2><p>Set the download location and the media library directory read by Emby / Plex.</p></div></header><div class="module-content"><div class="grid2">${field("Download directory",input("org-source",o.source),"Directory where the downloader saves media content")}${field("Media library directory",input("org-target",o.target),"Directory read by Emby / Plex")}</div><div class="organizer-file-settings">${field("Media extensions (one per line)",textarea("org-extensions",list(o.extensions).join("\n")),"Used to identify media files that should be organized")}</div><div class="module-actions">${button("Save directories",'id="save-organizer" class="primary"')}</div></div></article>${configList("Downloader","client",c.clients,x=>`${clientName(x)}${x.url?` · ${x.url}`:""}`,"02")}${sourceSettings(c,"03")}<article class="settings-module spec-section diagnostic-module"><header><span class="module-no">04</span><div><h2>Diagnostics</h2><p>Inspect errors and configuration when connections or organization fail.</p></div></header><div class="module-content"><details class="technical diagnostic-drawer"><summary>View runtime diagnostics</summary><div class="diagnostic-actions">${button("Validate configuration",'id="validate-config"')}</div><div id="runtime-diagnostics">${diagnostics()}</div></details></div></article></div></section>`}
function configList(title,kind,values,detail,index="03"){return`<article class="settings-module spec-section connector-module"><header><span class="module-no">${index}</span><div><h2>${title}</h2><p>${kind==="client"?"Connect a downloader for new resources and existing tasks.":"Configure independently."}</p></div></header><div class="module-content"><div class="module-top-action">${kind==="client"&&Object.keys(values||{}).length?"":button("Add",`id="add-${kind}"`)}</div><div class="unit-grid config-list">${Object.values(values||{}).map(x=>{const status=kind==="client"?clientStatus(x):null,name=kind==="client"?clientName(x):sourceName(x);return`<button class="config-unit" data-${kind}="${esc(x.id)}"><span class="unit-kicker">${kind==="client"?"Downloader":"Content source"}</span><strong>${esc(name)}</strong><small>${esc(detail(x))}${status?.error?` · ${esc(status.error)}`:""}</small><span class="unit-state ${status?.kind==="conflict"?"attention":x.enabled===false?"muted":"resolved"}">${status?.kind==="conflict"?"Connection failed":x.enabled===false?"Disabled":status?.text||"Configured"}</span><span class="unit-arrow">→</span></button>`}).join("")||`<div class="empty">Not configured.</div>`}</div></div></article>`}
function clientStatus(client){if(!client.enabled)return{kind:"unknown",text:"Disabled"};const status=state.clientStatuses.find(x=>x.id===client.id);if(!status)return{kind:"unknown",text:"Not checked"};return status.reachable?{kind:"complete",text:formatMessage("Reachable · {latency} ms",{latency:status.latency_ms||0})}:{kind:"conflict",text:"Connection failed",error:status.error}}
function diagnostics(){const d=state.diagnostics||{};return`${state.syncError?`<div class="notice error compact-notice"><strong>Unable to refresh library status</strong><p>${esc(state.syncError)}</p></div>`:""}<div class="diagnostic-grid"><div><small>Runtime configuration</small><strong>${esc(d.runtime_config||"Unknown")}</strong></div>${operation("Latest automation cycle",d.last_cycle)}${operation("Latest migration",d.last_migration)}${operation("Latest backfill",d.last_backfill)}</div>`}
function operation(label,v){return`<div><small>${label}</small><strong>${v?esc(v.status):"No record yet"}</strong>${v?`<small>${esc(formatTime(v.finished_at))} · ${v.duration_ms} ms</small>${renderIssues(v.issues)}`:""}</div>`}function formatTime(v){const d=new Date(v);return Number.isNaN(d.valueOf())?v:d.toLocaleString(currentLocale()==="zh-CN"?"zh-CN":"en")}

async function toggleBuiltinSource(id){try{if(!BUILTIN_SOURCES.includes(id))throw new Error("Unknown built-in source");const current=state.config.sources?.[id]||{id,provider:id,rss:[],priority:0,enabled:false},body={id,provider:id,enabled:!current.enabled,priority:Number(current.priority||0)};if(list(current.rss).length)body.rss=list(current.rss);await api(`/ui/sources/${encodeURIComponent(id)}`,{method:"PUT",body:JSON.stringify(body)});toast(body.enabled?formatMessage("{name} enabled",{name:SOURCE_NAMES[id]}):formatMessage("{name} disabled",{name:SOURCE_NAMES[id]}));await refresh()}catch(e){toast(formatMessage("Source update failed: {error}",{error:e.message}))}}
export function sourceSettings(c,index="04"){const sources=c.sources||{},caps=c.source_capabilities||{};const builtins=BUILTIN_SOURCES.map(id=>{const source=sources[id]||{id,provider:id,rss:[],priority:0,enabled:false},enabled=Boolean(source.enabled),cap=caps[id]||{},customRSS=list(source.rss).length;return`<article class="source-choice ${enabled?"enabled":""}"><div class="source-choice-head"><strong>${esc(SOURCE_NAMES[id])}</strong><span>${enabled?"Enabled":"Disabled"}</span></div><small>${customRSS?formatMessage("{count} custom RSS",{count:customRSS}):"Default RSS"}${cap.historical?`<span> · ${translate("Historical search available")}</span>`:""}</small><div class="source-actions">${button("RSS",`type="button" data-source-config="${id}" class="quiet-button"`)}${button(enabled?"Disable":"Enable",`type="button" data-toggle-source="${id}" class="${enabled?"":"primary"}"`)}</div></article>`}).join("");const custom=Object.values(sources).filter(x=>x.provider==="generic");return`<article class="settings-module spec-section source-module"><header><span class="module-no">${index}</span><div><h2>Content source</h2><p>Enable sources used to discover, search, and download series. Personal or group RSS feeds are supported.</p></div></header><div class="module-content"><div class="module-top-action">${button("Add custom source",'id="add-source"')}</div><div class="source-choices">${builtins}</div>${custom.length?`<details class="subpanel" open><summary>${formatMessage("Custom sources ({count})",{count:custom.length})}</summary><div class="unit-grid config-list">${custom.map(x=>`<button type="button" class="config-unit" data-source="${esc(x.id)}"><span class="unit-kicker">Custom source</span><strong>${esc(sourceName(x))}</strong><small>${[list(x.rss).length?formatMessage("{count} RSS",{count:list(x.rss).length}):"",x.search?.url_template?"Searchable":""].filter(Boolean).join(" · ")||"Not configured"}</small><span class="unit-state ${x.enabled===false?"muted":"resolved"}">${x.enabled===false?"Disabled":"Enabled"}</span><span class="unit-arrow">→</span></button>`).join("")}</div></details>`:""}</div></article>`}
function bindNavigation(){
  $$("[data-view]").forEach(x=>x.onclick=async()=>{state.view=x.dataset.view;render();window.scrollTo({top:0});if(state.view==="settings")await loadClientStatuses();if(state.view==="discovery")await loadRSSDiscoveries()});
  $$("[data-scroll]").forEach(x=>x.onclick=()=>scrollToID(x.dataset.scroll));
}
function bindDiscoveryControls(){
  $("#discovery-order-open")?.addEventListener("click",openDiscoveryOrder);
  $("#rss-discovery-filter")?.addEventListener("input",e=>{state.discoveryLocalQuery=e.target.value;const el=$("#rss-discovery-results");if(el)el.innerHTML=renderRSSDiscoveries();$$("[data-accept-rss]").forEach(x=>x.onclick=()=>openDiscoverySetup(state.rssDiscoveries[Number(x.dataset.acceptRss)],null))});
  $$("[data-accept-rss]").forEach(x=>x.onclick=()=>openDiscoverySetup(state.rssDiscoveries[Number(x.dataset.acceptRss)],null));
  $$("[data-search-release]").forEach(x=>x.onclick=()=>{const [g,r]=x.dataset.searchRelease.split(":").map(Number);selectSearchRelease(g,r)});
  $("#rss-discovery-refresh")?.addEventListener("click",refreshRSSDiscoveries);
  $("#rss-discovery-reload")?.addEventListener("click",loadRSSDiscoveries);
  $("#discovery-search")?.addEventListener("click",searchDiscovery);
  $("#discovery-query")?.addEventListener("keydown",e=>{if(e.key==="Enter")searchDiscovery()});
  updateRSSControls();
}
function bindMigrationControls(){
  bindMigrationPlanControls(document,migrationPlan);
  $$("[data-migration-apply]").forEach(x=>x.onclick=()=>migrationApply(x));
  $$("[data-migration-type]").forEach(x=>{const unit=x.closest("[data-migration-unit]");x.onchange=()=>updateMigrationType(unit,x.value)});
}
function bindEntryControls(){
  $("#run-automation")?.addEventListener("click",()=>runAutomation());
  $("#refresh-page")?.addEventListener("click",()=>refresh());
  $("#entry-search")?.addEventListener("input",e=>{state.entryQuery=e.target.value;$("#entry-results").innerHTML=entryList();bindEntryItems($("#entry-results"),loadEntry)});
  $("#close-entry")?.addEventListener("click",()=>{clearEntrySelection(state);render()});
  $("#save-entry")?.addEventListener("click",saveEntry);
  $("#preview-entry")?.addEventListener("click",previewEntry);
  bindSeasonActions();
  bindMappings();
  bindRemovers();
}
function bindSettingsControls(){
  $("#save-organizer")?.addEventListener("click",saveOrganizer);
  $("#validate-config")?.addEventListener("click",validateConfig);
  $("#add-client")?.addEventListener("click",()=>openClient(newClientModel()));
  $$("[data-client]").forEach(x=>x.onclick=()=>openClient(state.config.clients[x.dataset.client]));
  $("#add-source")?.addEventListener("click",()=>openSource({id:"",provider:"generic",rss:null,search:null,priority:0,enabled:true}));
  $$("[data-source]").forEach(x=>x.onclick=()=>openSource(state.config.sources[x.dataset.source]));
  $$("[data-source-config]").forEach(x=>x.onclick=()=>openSource(state.config.sources[x.dataset.sourceConfig]||{id:x.dataset.sourceConfig,provider:x.dataset.sourceConfig,rss:[],priority:0,enabled:false}));
  $$("[data-toggle-source]").forEach(x=>x.onclick=()=>toggleBuiltinSource(x.dataset.toggleSource));
}
export function bind(){
  bindNavigation();
  bindDiscoveryControls();
  bindMigrationControls();
  bindEntryControls();
  bindSettingsControls();
}
export function bindMigrationPlanControls(root,handler=migrationPlan){
  const buttons=[...(root?.querySelectorAll?.("[data-migration-plan]")||[])];
  for(const button of buttons)button.addEventListener("click",handler);
  return buttons.length;
}

export async function migrationPlan(){
  if(state.migrationScanning)return;
  state.migrationScanning=true;
  state.error="";
  render();
  try{
    state.migration=await api("/ui/migrations/plan",{method:"POST",body:"{}",signal:AbortSignal.timeout(120000)});
  }catch(e){
    state.error=formatMessage("Migration scan failed: {error}",{error:e.message});
  }finally{
    state.migrationScanning=false;
    render();
  }
}

export function updateMigrationType(unit,mediaType){const movie=mediaType==="movie",slot=unit.querySelector('[data-migration-season-slot]'),existing=unit.querySelector('[data-migration-season]'),id=unit.querySelector('[data-migration-title]').id.replace(/-title$/,"");slot.innerHTML=migrationSeasonField(id,mediaType,existing?.value||1);slot.hidden=movie;unit.querySelector('[data-migration-movie-classify]').hidden=!movie}
function bindSeasonActions(){$$('[data-save-folder]').forEach(x=>x.onclick=()=>saveFolder(x.dataset.saveFolder));$$('[data-backfill]').forEach(x=>x.onclick=()=>backfill(x.dataset.backfill));$$('[data-confirm-repair]').forEach(x=>x.onclick=()=>openRepairConfirmation(x.dataset.repairSeason,x.dataset.confirmRepair))}
function bindRemovers(){$$('[data-remove-row]').forEach(x=>x.onclick=()=>x.closest(".structured-row").remove());bindEntryItems($("#entry-results"),loadEntry);bindEntryItems($("#entry-attention"),loadEntry)}
function bindMappings(){$$('[data-add-structured]').forEach(x=>x.onclick=()=>{const key=x.dataset.addStructured,fields=[["source","Filename (without path)"],["season","Season"],["episode","Episode"]];x.previousElementSibling.insertAdjacentHTML("beforeend",structuredRow(key,fields));bindRemovers()})}
function readSpecials(root){return [...root.querySelectorAll(`[data-structured-row="specials"]`)].map(row=>Object.fromEntries([...row.querySelectorAll("[data-field]")].map(i=>[i.dataset.field,i.dataset.field==="source"?i.value.trim():Number(i.value)])))}
function migrationAction(trigger){const unit=trigger.closest('[data-migration-unit]'),group=list(state.migration?.groups).find(g=>g.key===trigger.dataset.migrationApply),plans=list(group?.plans),tasks=plans.map(p=>({client:p.client,task_id:p.task_id,info_hash:p.info_hash||""})),title=unit?.querySelector('[data-migration-title]')?.value.trim()||"",mediaType=unit?.querySelector('[data-migration-type]')?.value||group?.media_type||"series",season=migrationSeason(mediaType,unit?.querySelector('[data-migration-season]')?.value??group?.season),year=Number(unit?.querySelector('[data-migration-year]')?.value||0),filters=readFilters(unit),movie=mediaType==="movie"?{classify:buildMovieClassify(unit?.querySelector('[data-migration-classify]')?.value||"")}:undefined;if(!group)throw new Error("Migration plan is stale, Rescan");if(!title)throw new Error("Enter Title");return{group,plans,payload:{key:group.key,entry_key:group.entry_key||"",title,season,year,media_type:mediaType,filters,movie,tasks}}}

export async function saveEntryWorkflow(apiFn,key,body,reloadFn){
  await apiFn(`${entryURL(key)}/declaration`,{method:"PUT",body:JSON.stringify(body)});
  await reloadFn();
  return key;
}
export async function migrationApplyWorkflow(apiFn,payload,reloadFn){
  const signal=()=>AbortSignal.timeout(120000);
  const result=await apiFn("/ui/migrations/apply",{method:"POST",body:JSON.stringify(payload),signal:signal()});
  let plan;
  try{plan=await apiFn("/ui/migrations/plan",{method:"POST",body:"{}",signal:signal()})}
  catch(error){error.message=formatMessage("Migration completed, but rescan failed: {error}",{error:error.message});throw error}
  await reloadFn();
  return{result,plan};
}

async function executeMigration(action){state.migrationBusy=action.group.key;render();try{const done=await migrationApplyWorkflow(api,action.payload,reloadProjection);state.migration=done.plan;state.migrationBusy="";const applied=list(done.result.applied).length;toast(applied?formatMessage("Migration complete: processed {count} download tasks",{count:applied}):"Status refreshed; there is no migration action to execute");scrollToID("migration")}catch(e){state.migrationBusy="";fail(e.message);scrollToID("migration")}}
function migrationApply(trigger){try{const action=migrationAction(trigger),model=migrationConfirmationModel(action.plans,{title:action.payload.title,mediaType:action.payload.media_type,season:action.payload.season});confirmAction(model,()=>executeMigration(action))}catch(e){toast(e.message)}}
export function rssObservationPresentation(source){const date=source.updated_at?new Date(source.updated_at):null,time=date&&!Number.isNaN(date.getTime())?date.toLocaleString():"";if(source.status==="pending")return "Waiting for first update";if(source.status==="error")return source.stale?formatMessage("Update failed · retaining results from {time}",{time:time||translate("last time")}):"Update failed · No available results";if(source.status==="partial")return formatMessage("Partial results · {time}",{time});return time?formatMessage("Updated · {time}",{time}):"Not updated yet"}
function renderRSSStatus(){const progress=state.rssRefreshing?"Background update in progress. Existing results are shown now; reload later for the latest results.":"Updates run periodically in the background. Return to this page or click “Reload” to view the latest results.";return `<div class="rss-status"><p>${progress}</p>${state.rssSources.length?`<ul>${state.rssSources.map(source=>`<li><strong>${esc(sourceName(state.config?.sources?.[source.source_id]||{id:source.source_id}))}</strong><span>${esc(rssObservationPresentation(source))}</span></li>`).join("")}</ul>`:""}</div>`}
function updateRSSControls(){const read=$("#rss-discovery-reload"),refresh=$("#rss-discovery-refresh");if(read){read.disabled=state.rssReadPending;read.textContent=state.rssReadPending?"Reload in …":"Reload results"}if(refresh){refresh.disabled=state.rssRefreshPending||state.rssRefreshing;refresh.textContent=state.rssRefreshPending?"Submitting…":state.rssRefreshing?"Updating in background…":"Refresh RSS"}}
function updateRSSView(){updateDiscoveryCounts();const status=$("#rss-discovery-status"),results=$("#rss-discovery-results");if(status)status.innerHTML=renderRSSStatus();if(results){results.innerHTML=renderRSSDiscoveries();results.querySelectorAll('[data-accept-rss]').forEach(x=>x.onclick=()=>openDiscoverySetup(state.rssDiscoveries[Number(x.dataset.acceptRss)],null))}updateRSSControls()}
async function refreshRSSDiscoveries(){if(state.rssRefreshPending)return;state.rssRefreshPending=true;updateRSSControls();try{const result=await api("/ui/discovery/rss/refresh",{method:"POST",body:"{}"});await loadRSSDiscoveries();toast(result.status==="coalesced"?"RSS update is already running or queued":"Submitted background RSS update; reload later to see results")}catch(e){toast(formatMessage("RSS update could not be submitted: {error}",{error:e.message}))}finally{state.rssRefreshPending=false;updateRSSControls()}}
function updateDiscoveryCounts(){const count=$("[data-discovery-count]");if(count)count.textContent=String(state.rssDiscoveries.length)}
async function loadRSSDiscoveries(){if(!state.config||!Object.values(state.config.sources||{}).some(x=>x.enabled&&state.config.source_capabilities?.[x.id]?.current))return;if(state.rssReadPending)return;state.rssReadPending=true;updateRSSControls();try{const r=await api("/ui/discovery/rss");state.rssDiscoveries=list(r.groups);state.rssDiscoveryIssues=list(r.issues);state.rssSources=list(r.sources);state.rssRefreshing=Boolean(r.refreshing);state.rssDiscoveryError=""}catch(e){state.rssDiscoveryError=e.message}finally{state.rssReadPending=false;updateRSSView()}}

async function searchDiscovery(){const q=$("#discovery-query").value.trim(),source=$("#discovery-source").value;if(!q)return toast("Enter a search term");state.discoveryQuery=q;$("#discovery-results").innerHTML=`<div class="empty">Searching…</div>`;try{const r=await api(`/ui/discovery/search?source=${encodeURIComponent(source)}&q=${encodeURIComponent(q)}`,{signal:AbortSignal.timeout(120000)});state.discoveries=list(r.groups).filter(x=>x.media_type!=="movie");$("#discovery-results").innerHTML=renderDiscoveries();$$('[data-search-release]').forEach(x=>x.onclick=()=>{const [g,ri]=x.dataset.searchRelease.split(':').map(Number);selectSearchRelease(g,ri)})}catch(e){$("#discovery-results").innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
function selectSearchRelease(groupIndex,releaseIndex){const group=state.discoveries[groupIndex],release=group?.releases?.[releaseIndex],source=$("#discovery-source")?.value,query=state.discoveryQuery;if(!group||!release||!source||!query)return;if(group.entry_key)return acquireDiscovery(group.entry_key,source,query,release);openDiscoverySetup(group,{source,query,release})}
function setupFilterEditor(group){return filterEditor({},group||{})}
function readSetupFilters(){const root=document.querySelector(".modal .filter-editor")||document;return readFilters(root)}
function openDiscoverySetup(group,acquire){if(!group)return;const source=acquire?.source||group.source_ids?.[0]||"",sourceLabel=id=>sourceName(state.config.sources?.[id]||{id}),sourceText=acquire?sourceLabel(source):list(group.source_ids).map(sourceLabel).join(", ");modal(`<h2>${acquire?"Add and acquire":"Follow this title"}</h2><div class="discovery-confirm"><strong>${esc(group.title||"Unknown title")}${group.year?` (${group.year})`:""}</strong><small>${esc([group.media_type==="movie"?translate("Movie"):group.season?formatMessage("Season {number}",{number:String(group.season).padStart(2,"0")}):translate("Series"),observedText(group),sourceText].filter(Boolean).join(" · "))}</small></div><div class="grid2">${field("Title",input("setup-title",group.title||""))}${field("Year",input("setup-year",group.year||0,"number"))}</div><details class="subpanel"><summary>More settings</summary><div class="grid2">${field("Media library name",input("setup-output",group.title||""))}</div><h3>Release filters</h3>${setupFilterEditor(group)}</details><div class="toolbar end">${button("Cancel",'id="cancel"')}${button(acquire?"Add and acquire":"Start following",'id="save-discovery-entry" class="primary"')}</div>`);$("#cancel").onclick=closeModal;$("#save-discovery-entry").onclick=()=>createDiscoveryEntry(group,source,acquire)}
async function createDiscoveryEntry(group,source,acquire){try{const title=$("#setup-title").value.trim(),year=Number($("#setup-year").value||0);if(!title)throw new Error("Title cannot be empty");if(!Number.isInteger(year)||year<0)throw new Error("Year must be a non-negative integer");const filters=readSetupFilters(),sources=discoverySources(group,acquire?.source||"");if(!sources.length&&source)sources.push(source);const body={title,year,enabled:true,sources,filters,output:{title:$("#setup-output").value.trim()},blacklist:[]};const created=await api(`/ui/catalog/${encodeURIComponent(group.media_type)}`,{method:"POST",body:JSON.stringify({season:group.season||0,declaration:body})});closeModal();if(acquire)await acquireDiscovery(created.entry.key,acquire.source,acquire.query,acquire.release);await reloadProjection();if(!acquire)toast("Following started");loadRSSDiscoveries()}catch(e){modalError(e.message)}}
async function acquireDiscovery(entry,source,query,release){try{const r=await api("/ui/discovery/acquire",{method:"POST",body:JSON.stringify({entry_key:entry,source_id:source,query,release})});await reloadProjection({renderPage:false});toast(formatMessage("Sent to Downloader: {result}",{result:r.acquisition?.task_id||r.acquisition?.decision||"accepted"}))}catch(e){toast(formatMessage("Send failed: {error}",{error:e.message}))}}

async function loadEntry(id){try{state.entry=await api(entryURL(id));state.seasons=list(state.entry?.seasons);state.folders=list(state.entry?.folders);state.view="entries";render();window.scrollTo({top:0,behavior:"smooth"})}catch(e){fail(e.message)}}
async function saveEntry(){try{const root=$("#save-entry").closest(".entry-editor"),d=state.entry.declaration,title=$("#entry-title").value.trim(),year=Number($("#entry-year").value||0);if(!title)throw new Error("Title cannot be empty");if(!Number.isInteger(year)||year<0)throw new Error("Year must be a non-negative integer");const body=buildEntryDeclaration(d,{title,year,enabled:$("#entry-enabled").checked,sources:$$('[data-entry-source]:checked').map(x=>x.dataset.entrySource),filters:readFilters(root),specials:readSpecials(root),output_title:$("#entry-output-title").value,blacklist:$("#entry-blacklist").value});await saveEntryWorkflow(api,state.entry.entry.key,body,reloadProjection);toast("Title settings saved");scrollToID("entries")}catch(e){const el=$("#entry-error");if(el)el.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;else toast(e.message)}}
function renderPreviewResult(r){if(r.items?.length)return`<div class="preview"><h3>${formatMessage("Movie file · {decision}",{decision:esc(translate(r.decision))})}</h3>${r.items.map(x=>`<div><strong>${esc(translate(({link:"✓ release",existing:"✓ Already exists",excluded:"× Excluded",conflict:"! Needs confirmation"})[x.action]||x.action))}</strong> <code>${esc(x.relative_source||x.source)}</code>${x.destination?`<br>→ <code>${esc(x.destination)}</code>`:""}${x.detail?`<small>${esc(x.detail)}</small>`:""}</div>`).join("")}</div>`;const p=previewPresentation(r),ep=x=>x?`S${String(x.season).padStart(2,"0")}E${String(x.episode_start).padStart(2,"0")}`:"Unknown";if(p.excluded)return`<div class="notice"><strong>Excluded</strong><p>Matched blacklist: <code>${esc(p.rule)}</code></p><small>This file was skipped, will not be added to the media library.</small></div>`;return`<div class="preview"><dl><dt>Source title</dt><dd>${esc(p.sourceTitle||"Unknown")}</dd><dt>Output title</dt><dd>${esc(p.outputTitle||"Not set")}</dd><dt>Source</dt><dd>${esc(ep(p.source))}</dd><dt>Target </dt><dd>${esc(ep(p.target))}</dd><dt>Expected media library path</dt><dd>${esc(p.path||"Unknown")}</dd><dt>Decision</dt><dd>${esc(r.decision)}</dd><dt>Reason</dt><dd>${esc(r.reason||"none")}</dd></dl></div>`}
async function previewEntry(){const name=$("#preview-name").value.trim();if(!previewNameValid(name))return toast("Enter a release name or filename");try{const r=await api(`${entryURL(state.entry.entry.key)}/preview`,{method:"POST",body:JSON.stringify({name})});$("#preview-result").innerHTML=renderPreviewResult(r)+renderIssues(r.issues)}catch(e){$("#preview-result").innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function saveFolder(folder){try{const card=[...document.querySelectorAll('[data-folder-card]')].find(x=>x.dataset.folderCard===folder);if(!card)throw new Error("Source folder not found");const season=Number(card.querySelector("[data-folder-season]").value),episodeOffset=Number(card.querySelector("[data-folder-episode-offset]").value||0);if(!Number.isInteger(season)||season<0||season>99||!Number.isInteger(episodeOffset))throw new Error("Target season must be an integer from 0 to 99, and episode offset must be an integer");await api(`${entryURL(state.entry.entry.key)}/folders/${encodeURIComponent(folder)}/projection`,{method:"PUT",body:JSON.stringify({season,episode_offset:episodeOffset})});await reloadProjection();toast("Folder settings saved")}catch(e){toast(formatMessage("Save failed: {error}",{error:e.message}))}}
async function backfill(season){try{const id=state.entry.entry.key,from=Number($(`[data-range-from="${season}"]`)?.value||0),through=Number($(`[data-range-through="${season}"]`)?.value||0),buttonEl=$(`[data-backfill="${season}"]`);if(from<=0||through<from)return toast("Enter a valid completion range");if(buttonEl){buttonEl.disabled=true;buttonEl.textContent="Searching…"}const result=await api(`${entryURL(id)}/seasons/${season}/backfill`,{method:"POST",body:JSON.stringify({from,through}),signal:AbortSignal.timeout(300000)});await reloadProjection();const selected=list(result.selected).length,reviews=list(result.reviews).length,acquisitions=list(result.acquisitions),issues=list(result.issues),submitted=acquisitions.filter(x=>x.decision==="submitted"||x.decision==="recovered").length,issueEl=$("#entry-error");if(issueEl)issueEl.innerHTML=renderIssues(issues);if(reviews)toast(formatMessage("Range completion finished: {submitted} submitted, {reviews} candidates need confirmation",{submitted,reviews}));else if(issues.length)toast(formatMessage("Range completion finished: {selected} selected, {submitted} submitted; review the issues",{selected,submitted}));else if(selected===0)toast("There are currently no missing or available resources in this range");else toast(formatMessage("Range completion finished: {selected} resources selected, {submitted} downloads submitted",{selected,submitted}))}catch(e){const el=$("#entry-error");if(el)el.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;else toast(e.message)}}
function openRepairConfirmation(season,reviewID){const s=state.seasons.find(x=>String(x.season)===String(season)),review=list(s?.repair_reviews).find(x=>x.id===reviewID),r=review?.release||{},name=r.media_name||r.title||"this candidate";confirmAction({title:"Confirm low-confidence completion",message:formatMessage("{name} is a manual candidate retained for this missing episode. After confirmation it will be sent immediately to the downloader; if the file, rules, or candidate state has changed, the backend will reject the stale confirmation.",{name}),confirmLabel:"Use this version"},()=>confirmRepair(season,reviewID))}
async function confirmRepair(season,reviewID){try{const id=state.entry.entry.key,result=await api(`${entryURL(id)}/seasons/${season}/repairs/${encodeURIComponent(reviewID)}/confirm`,{method:"POST",body:"{}",signal:AbortSignal.timeout(120000)}),acquisitions=list(result.acquisitions),submitted=acquisitions.filter(x=>x.decision==="submitted"||x.decision==="recovered").length;await reloadProjection();toast(submitted?"Confirmed and sent to Downloader":"Confirmation complete, but the downloader did not accept the task")}catch(e){const el=$("#entry-error");if(el)el.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;else toast(e.message)}}
async function saveOrganizer(){try{const body={source:$("#org-source").value.trim(),target:$("#org-target").value.trim(),extensions:lines($("#org-extensions").value)};await api("/ui/config/organizer",{method:"PUT",body:JSON.stringify(body)});toast("Working directories saved");await refresh()}catch(e){toast(formatMessage("Save failed: {error}",{error:e.message}))}}
async function validateConfig(){try{await api("/ui/config/validate",{method:"POST",body:"{}"});toast("Configuration check passed")}catch(e){fail(e.message)}}

function credentialField(isSet=false){return field("Password / RPC key",input("client-password","","password",isSet?"Saved; leave blank to keep":"Not set"),"Stored encrypted after saving; the original password is not shown again")+`<label class="check"><input id="client-clear-password" type="checkbox">Clear saved password</label>`}
function pathRows(values){return values.map(v=>`<div class="structured-row path-row">${field("Downloader-visible path",`<input data-remote value="${esc(v.remote)}">`)}${field("aninode visible path",`<input data-local value="${esc(v.local)}">`)}${button("Remove",'type="button" data-remove-row class="danger"')}</div>`).join("")}
function openClient(c){modal(`<h2>${c.id?formatMessage("Edit {name}",{name:esc(clientName(c))}):"Add downloader"}</h2><div class="grid2">${field("Type",`<select id="client-type">${options(["qbittorrent","transmission","aria2"],c.type)}</select>`)}${field("Address",input("client-url",c.url))}${field("Username",input("client-user",c.username||""))}</div><label class="check"><input id="client-enabled" type="checkbox" ${checked(c.enabled)}>Enable downloader</label><details class="subpanel" open><summary>Authentication</summary>${credentialField(c.credential_set)}</details><details class="subpanel"><summary>Path mappings</summary><div id="path-list" class="structured-list">${pathRows(c.path_mappings||[])}</div>${button("Add path mapping",'id="add-path"')}</details><div class="toolbar between">${c.id?button("Delete",'id="delete-client" class="danger"'):"<span></span>"}<div>${button("Cancel",'id="cancel"')}${button("Save",'id="save-client" class="primary"')}</div></div>`);bindRemovers();$("#add-path").onclick=()=>{$("#path-list").insertAdjacentHTML("beforeend",pathRows([{remote:"",local:""}]));bindRemovers()};$("#cancel").onclick=closeModal;$("#save-client").onclick=()=>saveClient(c);$("#delete-client")?.addEventListener("click",()=>removeConfig("clients",c.id))}
async function saveClient(original){try{const type=$("#client-type").value,id=original.id||nextConfigID("clients",type),body={id,type,url:$("#client-url").value.trim(),username:$("#client-user").value.trim(),path_mappings:$$('.path-row').map(row=>({remote:row.querySelector('[data-remote]').value.trim(),local:row.querySelector('[data-local]').value.trim()})),enabled:$("#client-enabled").checked};const password=$("#client-password").value;if($("#client-clear-password").checked)body.password="";else if(password!=="")body.password=password;await api(`/ui/clients/${encodeURIComponent(id)}`,{method:"PUT",body:JSON.stringify(body)});closeModal();toast("Downloader saved");await refresh()}catch(e){modalError(e.message)}}


export function buildSourcePayload(original,values={}){const builtin=BUILTIN_SOURCES.includes(original?.provider),mode=builtin?(values.mode||"default"):"custom",rssURLs=[...new Set(list(values.rssURLs).map(x=>String(x||"").trim()).filter(Boolean))],searchTemplate=builtin?"":String(values.searchTemplate||"").trim();if(builtin&&mode==="custom"&&!rssURLs.length)throw new Error("Add at least one RSS URL");if(!builtin&&!rssURLs.length&&!searchTemplate)throw new Error("Custom source requires at least one RSS URL or a search URL");const id=builtin?original.provider:(original.id||values.id);if(!id)throw new Error("Content source ID cannot be empty");const priority=Number(values.priority||0);if(!Number.isFinite(priority))throw new Error("Priority must be a number");const body={id,provider:builtin?original.provider:"generic",priority,enabled:Boolean(values.enabled)};if(mode==="custom"&&rssURLs.length)body.rss=rssURLs.map(url=>({url}));if(searchTemplate)body.search={url_template:searchTemplate};return body}

function rssRows(values){return list(values).map(v=>`<div class="rss-row" data-rss-row><input data-rss-url type="url" value="${esc(v?.url||v||"")}" placeholder="https://…"><button type="button" data-remove-rss aria-label="Delete RSS">Delete</button></div>`).join("")}
function bindRSSRows(){$$('[data-remove-rss]').forEach(x=>x.onclick=()=>x.closest('[data-rss-row]').remove());$("#add-rss-row")?.addEventListener("click",()=>{$("#source-rss-rows").insertAdjacentHTML("beforeend",rssRows([""]));bindRSSRows()});$$('[name="source-rss-mode"]').forEach(x=>x.onchange=()=>{$("#source-rss-custom").hidden=x.value!=="custom"})}
function openSource(source){const builtin=BUILTIN_SOURCES.includes(source.provider),search=source.search||{},configured=list(source.rss),mode=configured.length?"custom":"default";modal(`<h2>${builtin?`${esc(sourceName(source))} RSS`:source.id?"Edit custom source":"Add custom source"}</h2><label class="check"><input id="source-enabled" type="checkbox" ${checked(source.enabled)}>Enable</label>${builtin?`<div class="choice-stack"><label class="choice-row"><input type="radio" name="source-rss-mode" value="default" ${mode==="default"?"checked":""}><span><strong>Use default RSS</strong><small>Recommended for most setups</small></span></label><label class="choice-row"><input type="radio" name="source-rss-mode" value="custom" ${mode==="custom"?"checked":""}><span><strong>Use custom RSS</strong><small>For example, a personal, release-group, or category RSS feed</small></span></label></div>`:""}<div id="source-rss-custom" ${builtin&&mode!=="custom"?"hidden":""}><div class="field"><span>RSS</span><div id="source-rss-rows" class="rss-rows">${rssRows(configured.length?configured:[""])}</div>${button("Add RSS",'id="add-rss-row" type="button"')}</div></div>${builtin?"":field("Search URL",input("source-search",search.url_template||"","text","https://example/search?q={query}"),"Use {query} as the search term")}<details class="subpanel"><summary>Advanced</summary>${field("Priority",input("source-priority",source.priority||0,"number"),"Used when multiple sources find the same resource")}</details><div class="toolbar between">${!builtin&&source.id?button("Delete",'id="delete-source" class="danger"'):"<span></span>"}<div>${button("Cancel",'id="cancel"')}${button("Save",'id="save-source" class="primary"')}</div></div>`);bindRSSRows();$("#cancel").onclick=closeModal;$("#save-source").onclick=()=>saveSource(source);$("#delete-source")?.addEventListener("click",()=>removeConfig("sources",source.id))}
async function saveSource(original){try{const builtin=BUILTIN_SOURCES.includes(original.provider),body=buildSourcePayload(original,{mode:builtin?document.querySelector('[name="source-rss-mode"]:checked')?.value:"custom",rssURLs:$$('[data-rss-url]').map(x=>x.value),searchTemplate:$("#source-search")?.value||"",priority:$("#source-priority").value,enabled:$("#source-enabled").checked,id:original.id||nextConfigID("sources","custom")});await api(`/ui/sources/${encodeURIComponent(body.id)}`,{method:"PUT",body:JSON.stringify(body)});closeModal();toast("Content source saved");await refresh()}catch(e){modalError(e.message)}}
async function loadClientStatuses(){try{state.clientStatuses=list(await api("/ui/clients/status"));if(state.view==="settings"&&!editingUI())render()}catch(e){toast(formatMessage("Downloader status check failed: {error}",{error:e.message}))}}
async function removeConfig(kind,id){const value=state.config?.[kind]?.[id],isClient=kind==="clients",label=isClient?clientName(value||{id}):sourceName(value||{id}),message=isClient?formatMessage("Delete {name}? This will leave no available downloader, so automatic acquisition will stop.",{name:label}):formatMessage("Delete {name}? If any title explicitly uses it, the backend will reject the deletion; update those title rules first.",{name:label});confirmAction({title:isClient?"Delete downloader":"Delete content source",message,confirmLabel:"Delete",danger:true},async()=>{try{await api(`/ui/${kind}/${encodeURIComponent(id)}`,{method:"DELETE"});toast("Deleted");await refresh()}catch(e){toast(formatMessage("Delete failed: {error}",{error:e.message}))}})}
async function syncRuntime(){if(!state.authenticated||document.visibilityState==="hidden")return;await reloadProjection({renderPage:true});if(state.view==="discovery")await loadRSSDiscoveries()}
if(typeof document!=="undefined"){await initI18n();installControls();localizeDOM(document);startSession();document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$(".modal"))closeModal()});document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")syncRuntime()});window.addEventListener("focus",syncRuntime)}

export function loginPage(setupRequired=false,message=""){
 return `<main id="main" class="login-page"><section class="login-card" aria-labelledby="login-title"><div class="brand"><strong>aninode</strong><span>media organizer</span></div><span class="overline">${setupRequired?"Welcome":"Welcome back"}</span><h1 id="login-title">${setupRequired?"Verify and set password":"Sign in"}</h1><p>${setupRequired?"Enter the one-time setup code from the host, then set an administrator password. The code is valid for 10 minutes and expires immediately after use.":"Enter your password to manage your media library."}</p><form id="login-form">${setupRequired?`<label class="field"><span>Setup code</span><input id="login-setup-code" name="setup-code" type="text" autocomplete="one-time-code" maxlength="64" required autofocus></label><small>${formatMessage("For Docker deployments, run {command} to retrieve the code. Run it again after expiration to generate a new one.",{command:"<code>docker compose exec aninode aninode setup-code</code>"})}</small>`:""}<label class="field"><span>${setupRequired?"New password":"Password"}</span><input id="login-password" name="password" type="password" autocomplete="${setupRequired?"new-password":"current-password"}" ${setupRequired?'minlength="8"':""} maxlength="1024" required ${setupRequired?"":"autofocus"}></label>${setupRequired?`<label class="field"><span>Confirm password</span><input id="login-confirm" name="password-confirm" type="password" autocomplete="new-password" minlength="8" maxlength="1024" required></label><small>Use at least 8 characters.</small>`:""}<div id="login-error" role="alert">${esc(message)}</div><button type="submit" class="primary">${setupRequired?"Verify and continue":"Sign in"}</button></form></section></main>`
}
function showLogin(setupRequired=false,message=""){
 sessionEpoch++;Object.assign(state,initialState());modalReturnFocus=null;
 $("#app").innerHTML=loginPage(setupRequired,message);$("#login-password").focus();
 $("#login-form").onsubmit=async e=>{
  e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type="submit"]'),password=$("#login-password").value;
  if(setupRequired&&password!==$("#login-confirm").value){$("#login-error").textContent="Passwords do not match";return}
  submit.disabled=true;$("#login-error").textContent="";
  try{const body={password};if(setupRequired)body.setup_code=$("#login-setup-code").value.trim();await api(setupRequired?"/auth/setup":"/auth/login",{method:"POST",body:JSON.stringify(body)});state.authenticated=true;shell();await refresh()}
  catch(e){if($("#login-error"))$("#login-error").textContent=e.message;if($("#login-password"))$("#login-password").value="";if($("#login-confirm"))$("#login-confirm").value=""}
  finally{submit.disabled=false}
 }
}
async function startSession(){
 $("#app").innerHTML='<main id="main" class="login-page"><p role="status">Connecting…</p></main>';
 try{const status=await api("/auth/status");if(status.authenticated){state.authenticated=true;shell();await refresh()}else showLogin(status.setup_required)}
 catch(e){$("#app").innerHTML=`<main id="main" class="login-page"><section class="login-card"><h1>Unable to connect</h1><p role="alert">${esc(e.message)}</p><button id="retry-login">Retry</button></section></main>`;$("#retry-login").onclick=startSession}
}
async function logout(){try{await api("/auth/logout",{method:"POST",body:"{}"});showLogin(false)}catch(e){toast(formatMessage("Sign out failed: {error}",{error:e.message}))}}
function openLoginPassword(){
 modal(`<h2>Change sign-in password</h2>${field("Current password",'<input id="current-password" type="password" autocomplete="current-password">')}${field("New password",'<input id="new-password" type="password" autocomplete="new-password" minlength="8" maxlength="1024">',"Use at least 8 characters.")}${field("Confirm new password",'<input id="confirm-password" type="password" autocomplete="new-password">')}<p>After saving, other browsers will need to sign in again.</p><div class="toolbar end">${button("Cancel",'id="cancel"')}${button("Save",'id="save-login-password" class="primary"')}</div>`);
 $("#cancel").onclick=closeModal;$("#save-login-password").onclick=async e=>{
  const control=e.currentTarget,password=$("#new-password").value;
  if(password!==$("#confirm-password").value){modalError("Passwords do not match");return}
  control.disabled=true;
  try{await api("/auth/password",{method:"POST",body:JSON.stringify({current_password:$("#current-password").value,password})});closeModal();toast("Sign-in password updated")}
  catch(e){modalError(e.message)}finally{control.disabled=false}
 }
}
